// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blk, uint256 ts, address actor) public {
        vm.assume(actor != address(c));
        blk = bound(blk, 0, 1000);
        ts = bound(ts, 1, 2**64); // timestamp strictly greater than initial pastBlockTime (0)
        vm.roll(blk);
        vm.warp(ts);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        // Reference invariant: once the call succeeds (requirements met), the payout
        // occurs iff the block number is divisible by 15, i.e. the contract's balance
        // becomes 0 exactly on divisible blocks. The mutant inverts the condition,
        // keeping its balance on divisible blocks and draining on non-divisible ones.
        assertTrue(ok && ((address(c).balance == 0) == (blk % 15 == 0)), "payout iff divisible-by-15 block");
    }
}
